mkdir -p /private/tmp/claude/claude-502/-Users-kenneth-Projects-JusPrin/57f57a8e-f983-48b3-8718-4f3fae9cc6dd/scratchpad && cat > /private/tmp/claude/claude-502/-Users-kenneth-Projects-JusPrin/57f57a8e-f983-48b3-8718-4f3fae9cc6dd/scratchpad/scan.py <<'EOF'
import json, os, re, sys, glob
root = os.path.expanduser("~/.claude/projects")
pat_live = re.compile(r"LIVE USAGE provider=(\w+) input_tokens=(\d+) cached_input_tokens=(\d+) output_tokens=(\d+)")
pat_run = re.compile(r"usage: input (\d+) \(cached (\d+)\), output (\d+)")
pat_text = re.compile(r"[^.\n]{0,160}\b(tokens? (?:per|a) (?:chat|conversation|run|turn)|per conversation|cost per chat|\$0\.\d+ a run)[^.\n]{0,160}", re.I)
for f in glob.glob(f"{root}/-Users-kenneth-Projects-JusPrin*/*.jsonl"):
    live=set(); run=[]; texts=[]; ts=None
    try:
        for line in open(f, errors="ignore"):
            if ts is None:
                m = re.search(r'"timestamp":"([^"]+)"', line)
                if m: ts = m.group(1)[:10]
            for m in pat_live.finditer(line): live.add(m.groups())
            for m in pat_run.finditer(line): run.append(m.groups())
            if '"type":"assistant"' in line:
                for m in pat_text.finditer(line): texts.append(m.group(0))
    except Exception as e: continue
    if live or run or texts:
        print(f"{ts} {os.path.basename(os.path.dirname(f))[-40:]}/{os.path.basename(f)[:8]} live={len(live)} run={len(run)} texts={len(texts)}")
        for t in texts[:3]: print("   >", t[:300].replace("\\n"," "))
EOF
